insert into public.translations (locale, key, value) values
  ('pt-BR', 'agent.kilo.tagline', $json$"O agente de linha de comando do Kilo Code, com aprovação automática no modo desenvolvimento."$json$::jsonb),
  ('en', 'agent.kilo.tagline', $json$"Kilo Code's command-line agent, with auto-approve in Development mode."$json$::jsonb),
  ('es', 'agent.kilo.tagline', $json$"El agente de línea de comandos de Kilo Code, con aprobación automática en el modo desarrollo."$json$::jsonb),
  ('zh-CN', 'agent.kilo.tagline', $json$"Kilo Code 的命令行智能体，开发模式下自动批准。"$json$::jsonb),
  ('hi', 'agent.kilo.tagline', $json$"Kilo Code का कमांड-लाइन एजेंट, डेवलपमेंट मोड में स्वतः स्वीकृति के साथ।"$json$::jsonb),
  ('ar', 'agent.kilo.tagline', $json$"وكيل Kilo Code لسطر الأوامر، مع الموافقة التلقائية في وضع التطوير."$json$::jsonb),
  ('fr', 'agent.kilo.tagline', $json$"L’agent en ligne de commande de Kilo Code, avec approbation automatique en mode développement."$json$::jsonb),
  ('ru', 'agent.kilo.tagline', $json$"Командный агент Kilo Code с автоматическим одобрением в режиме разработки."$json$::jsonb),
  ('ja', 'agent.kilo.tagline', $json$"Kilo Code のコマンドラインエージェント。開発モードでは自動承認します。"$json$::jsonb),
  ('de', 'agent.kilo.tagline', $json$"Der Kommandozeilen-Agent von Kilo Code, mit automatischer Freigabe im Entwicklungsmodus."$json$::jsonb),
  ('pt-BR', 'agent.openrouter.tagline', $json$"Uma chave para centenas de modelos pelo OpenRouter. Só responde por texto."$json$::jsonb),
  ('en', 'agent.openrouter.tagline', $json$"One key for hundreds of models through OpenRouter. Answers with text only."$json$::jsonb),
  ('es', 'agent.openrouter.tagline', $json$"Una clave para cientos de modelos a través de OpenRouter. Solo responde con texto."$json$::jsonb),
  ('zh-CN', 'agent.openrouter.tagline', $json$"通过 OpenRouter，一个密钥即可使用数百个模型。仅以文本回答。"$json$::jsonb),
  ('hi', 'agent.openrouter.tagline', $json$"OpenRouter के ज़रिए सैकड़ों मॉडल के लिए एक कुंजी। केवल टेक्स्ट में उत्तर देता है।"$json$::jsonb),
  ('ar', 'agent.openrouter.tagline', $json$"مفتاح واحد لمئات النماذج عبر OpenRouter. يجيب بالنص فقط."$json$::jsonb),
  ('fr', 'agent.openrouter.tagline', $json$"Une clé pour des centaines de modèles via OpenRouter. Répond uniquement par du texte."$json$::jsonb),
  ('ru', 'agent.openrouter.tagline', $json$"Один ключ для сотен моделей через OpenRouter. Отвечает только текстом."$json$::jsonb),
  ('ja', 'agent.openrouter.tagline', $json$"OpenRouter 経由で、1 つのキーで数百のモデルを利用できます。テキストでの回答のみです。"$json$::jsonb),
  ('de', 'agent.openrouter.tagline', $json$"Ein Schlüssel für Hunderte Modelle über OpenRouter. Antwortet nur mit Text."$json$::jsonb),
  ('pt-BR', 'agent.litellm.tagline', $json$"O seu próprio proxy LiteLLM, com os modelos que você configurou nele. Só responde por texto."$json$::jsonb),
  ('en', 'agent.litellm.tagline', $json$"Your own LiteLLM proxy, with the models you set up there. Answers with text only."$json$::jsonb),
  ('es', 'agent.litellm.tagline', $json$"Tu propio proxy LiteLLM, con los modelos que configuraste en él. Solo responde con texto."$json$::jsonb),
  ('zh-CN', 'agent.litellm.tagline', $json$"你自己的 LiteLLM 代理，使用你在其中配置的模型。仅以文本回答。"$json$::jsonb),
  ('hi', 'agent.litellm.tagline', $json$"आपका अपना LiteLLM प्रॉक्सी, जिसमें आपके सेट किए मॉडल हैं। केवल टेक्स्ट में उत्तर देता है।"$json$::jsonb),
  ('ar', 'agent.litellm.tagline', $json$"وكيل LiteLLM الخاص بك بالنماذج التي أعددتها فيه. يجيب بالنص فقط."$json$::jsonb),
  ('fr', 'agent.litellm.tagline', $json$"Votre propre proxy LiteLLM, avec les modèles que vous y avez configurés. Répond uniquement par du texte."$json$::jsonb),
  ('ru', 'agent.litellm.tagline', $json$"Ваш собственный прокси LiteLLM с моделями, которые вы в нём настроили. Отвечает только текстом."$json$::jsonb),
  ('ja', 'agent.litellm.tagline', $json$"ご自身の LiteLLM プロキシと、そこで設定したモデルを使います。テキストでの回答のみです。"$json$::jsonb),
  ('de', 'agent.litellm.tagline', $json$"Dein eigener LiteLLM-Proxy mit den dort eingerichteten Modellen. Antwortet nur mit Text."$json$::jsonb),
  ('pt-BR', 'kilo.auto', $json$"Aprovar automaticamente"$json$::jsonb),
  ('en', 'kilo.auto', $json$"Approve automatically"$json$::jsonb),
  ('es', 'kilo.auto', $json$"Aprobar automáticamente"$json$::jsonb),
  ('zh-CN', 'kilo.auto', $json$"自动批准"$json$::jsonb),
  ('hi', 'kilo.auto', $json$"स्वतः स्वीकृत करें"$json$::jsonb),
  ('ar', 'kilo.auto', $json$"الموافقة تلقائيًا"$json$::jsonb),
  ('fr', 'kilo.auto', $json$"Approuver automatiquement"$json$::jsonb),
  ('ru', 'kilo.auto', $json$"Одобрять автоматически"$json$::jsonb),
  ('ja', 'kilo.auto', $json$"自動で承認"$json$::jsonb),
  ('de', 'kilo.auto', $json$"Automatisch freigeben"$json$::jsonb),
  ('pt-BR', 'kilo.auto.hint', $json$"Roda `kilo run --auto`, aprovando o que o agente pedir. O modo desenvolvimento sempre liga; o planejamento sempre desliga."$json$::jsonb),
  ('en', 'kilo.auto.hint', $json$"Runs `kilo run --auto`, approving what the agent asks for. Development mode always turns this on; Planning mode always turns it off."$json$::jsonb),
  ('es', 'kilo.auto.hint', $json$"Ejecuta `kilo run --auto`, aprobando lo que el agente pida. El modo desarrollo siempre lo activa; el de planificación siempre lo desactiva."$json$::jsonb),
  ('zh-CN', 'kilo.auto.hint', $json$"运行 `kilo run --auto`，自动批准智能体的请求。开发模式始终开启，规划模式始终关闭。"$json$::jsonb),
  ('hi', 'kilo.auto.hint', $json$"`kilo run --auto` चलाता है और एजेंट जो माँगे उसे स्वीकृत करता है। डेवलपमेंट मोड इसे हमेशा चालू और प्लानिंग मोड हमेशा बंद रखता है।"$json$::jsonb),
  ('ar', 'kilo.auto.hint', $json$"يشغّل `kilo run --auto` ويوافق على ما يطلبه الوكيل. وضع التطوير يفعّله دائمًا، ووضع التخطيط يعطّله دائمًا."$json$::jsonb),
  ('fr', 'kilo.auto.hint', $json$"Lance `kilo run --auto` et approuve ce que l’agent demande. Le mode développement l’active toujours ; le mode planification le désactive toujours."$json$::jsonb),
  ('ru', 'kilo.auto.hint', $json$"Запускает `kilo run --auto` и одобряет всё, что просит агент. Режим разработки всегда включает это, режим планирования всегда выключает."$json$::jsonb),
  ('ja', 'kilo.auto.hint', $json$"`kilo run --auto` を実行し、エージェントの要求を承認します。開発モードでは常にオン、計画モードでは常にオフです。"$json$::jsonb),
  ('de', 'kilo.auto.hint', $json$"Führt `kilo run --auto` aus und genehmigt, was der Agent anfordert. Der Entwicklungsmodus schaltet das immer ein, der Planungsmodus immer aus."$json$::jsonb),
  ('pt-BR', 'kilo.mechanisms.none', $json$"O Kilo Code não tem flag de linha de comando para ligar ou desligar a busca na web e outras ferramentas: ele segue a configuração própria do Kilo."$json$::jsonb),
  ('en', 'kilo.mechanisms.none', $json$"Kilo Code has no command-line flag to turn web search or other tools on or off: it follows Kilo's own configuration."$json$::jsonb),
  ('es', 'kilo.mechanisms.none', $json$"Kilo Code no tiene un flag de línea de comandos para activar o desactivar la búsqueda web y otras herramientas: sigue la configuración propia de Kilo."$json$::jsonb),
  ('zh-CN', 'kilo.mechanisms.none', $json$"Kilo Code 没有用于开关网页搜索等工具的命令行参数：它遵循 Kilo 自身的配置。"$json$::jsonb),
  ('hi', 'kilo.mechanisms.none', $json$"Kilo Code में वेब खोज या अन्य टूल चालू/बंद करने का कोई कमांड-लाइन फ़्लैग नहीं है: यह Kilo की अपनी कॉन्फ़िगरेशन का पालन करता है।"$json$::jsonb),
  ('ar', 'kilo.mechanisms.none', $json$"لا يملك Kilo Code خيار سطر أوامر لتشغيل البحث على الويب أو الأدوات الأخرى أو إيقافها: يتبع إعدادات Kilo نفسها."$json$::jsonb),
  ('fr', 'kilo.mechanisms.none', $json$"Kilo Code n’a pas d’option de ligne de commande pour activer ou désactiver la recherche web et les autres outils : il suit la configuration propre de Kilo."$json$::jsonb),
  ('ru', 'kilo.mechanisms.none', $json$"У Kilo Code нет флага командной строки для включения или отключения веб-поиска и других инструментов: он следует собственной конфигурации Kilo."$json$::jsonb),
  ('ja', 'kilo.mechanisms.none', $json$"Kilo Code には、Web 検索などのツールをオン／オフするコマンドラインフラグがありません。Kilo 自身の設定に従います。"$json$::jsonb),
  ('de', 'kilo.mechanisms.none', $json$"Kilo Code hat kein Kommandozeilen-Flag, um Websuche oder andere Werkzeuge ein- oder auszuschalten: Es folgt Kilos eigener Konfiguration."$json$::jsonb),
  ('pt-BR', 'gateway.section.description', $json$"Para onde o JayV envia os pedidos e a chave que os assina. A chave fica só neste computador."$json$::jsonb),
  ('en', 'gateway.section.description', $json$"Where JayV sends the requests and the key that signs them. The key stays on this computer."$json$::jsonb),
  ('es', 'gateway.section.description', $json$"A dónde JayV envía las solicitudes y la clave que las firma. La clave se queda solo en este equipo."$json$::jsonb),
  ('zh-CN', 'gateway.section.description', $json$"JayV 发送请求的地址以及用于签名的密钥。密钥只保存在这台电脑上。"$json$::jsonb),
  ('hi', 'gateway.section.description', $json$"JayV अनुरोध कहाँ भेजता है और उन पर हस्ताक्षर करने वाली कुंजी। कुंजी केवल इसी कंप्यूटर पर रहती है।"$json$::jsonb),
  ('ar', 'gateway.section.description', $json$"الوجهة التي يرسل إليها JayV الطلبات والمفتاح الذي يوقّعها. يبقى المفتاح على هذا الحاسوب فقط."$json$::jsonb),
  ('fr', 'gateway.section.description', $json$"Où JayV envoie les requêtes et la clé qui les signe. La clé reste sur cet ordinateur."$json$::jsonb),
  ('ru', 'gateway.section.description', $json$"Куда JayV отправляет запросы и ключ, которым они подписываются. Ключ остаётся только на этом компьютере."$json$::jsonb),
  ('ja', 'gateway.section.description', $json$"JayV がリクエストを送る先と、それに署名するキーです。キーはこのコンピューターにのみ保存されます。"$json$::jsonb),
  ('de', 'gateway.section.description', $json$"Wohin JayV die Anfragen sendet und der Schlüssel, der sie signiert. Der Schlüssel bleibt nur auf diesem Computer."$json$::jsonb),
  ('pt-BR', 'gateway.baseUrl', $json$"Endereço base"$json$::jsonb),
