  ('pt-BR', 'gateway.baseUrl.hint.openrouter', $json$"O endereço do OpenRouter compatível com a API da OpenAI. Mude só para passar por um proxy seu."$json$::jsonb),
  ('en', 'gateway.baseUrl.hint.openrouter', $json$"OpenRouter's OpenAI-compatible address. Change it only to go through your own proxy."$json$::jsonb),
  ('es', 'gateway.baseUrl.hint.openrouter', $json$"La dirección de OpenRouter compatible con la API de OpenAI. Cámbiala solo para pasar por un proxy propio."$json$::jsonb),
  ('zh-CN', 'gateway.baseUrl.hint.openrouter', $json$"OpenRouter 兼容 OpenAI API 的地址。仅在通过你自己的代理时修改。"$json$::jsonb),
  ('hi', 'gateway.baseUrl.hint.openrouter', $json$"OpenRouter का OpenAI-संगत पता। केवल अपने प्रॉक्सी से जाने के लिए बदलें।"$json$::jsonb),
  ('ar', 'gateway.baseUrl.hint.openrouter', $json$"عنوان OpenRouter المتوافق مع واجهة OpenAI. غيّره فقط للمرور عبر وكيلك الخاص."$json$::jsonb),
  ('fr', 'gateway.baseUrl.hint.openrouter', $json$"L’adresse d’OpenRouter compatible avec l’API OpenAI. Ne la changez que pour passer par votre propre proxy."$json$::jsonb),
  ('ru', 'gateway.baseUrl.hint.openrouter', $json$"Адрес OpenRouter, совместимый с API OpenAI. Меняйте его, только чтобы идти через собственный прокси."$json$::jsonb),
  ('ja', 'gateway.baseUrl.hint.openrouter', $json$"OpenRouter の OpenAI 互換アドレスです。自分のプロキシを経由する場合のみ変更してください。"$json$::jsonb),
  ('de', 'gateway.baseUrl.hint.openrouter', $json$"Die OpenAI-kompatible Adresse von OpenRouter. Ändere sie nur, um über einen eigenen Proxy zu gehen."$json$::jsonb),
  ('pt-BR', 'gateway.baseUrl.hint.litellm', $json$"O endereço do seu proxy LiteLLM, por exemplo http://localhost:4000."$json$::jsonb),
  ('en', 'gateway.baseUrl.hint.litellm', $json$"The address of your LiteLLM proxy, for example http://localhost:4000."$json$::jsonb),
  ('es', 'gateway.baseUrl.hint.litellm', $json$"La dirección de tu proxy LiteLLM, por ejemplo http://localhost:4000."$json$::jsonb),
  ('zh-CN', 'gateway.baseUrl.hint.litellm', $json$"你的 LiteLLM 代理地址，例如 http://localhost:4000。"$json$::jsonb),
  ('hi', 'gateway.baseUrl.hint.litellm', $json$"आपके LiteLLM प्रॉक्सी का पता, जैसे http://localhost:4000।"$json$::jsonb),
  ('ar', 'gateway.baseUrl.hint.litellm', $json$"عنوان وكيل LiteLLM الخاص بك، مثل http://localhost:4000."$json$::jsonb),
  ('fr', 'gateway.baseUrl.hint.litellm', $json$"L’adresse de votre proxy LiteLLM, par exemple http://localhost:4000."$json$::jsonb),
  ('ru', 'gateway.baseUrl.hint.litellm', $json$"Адрес вашего прокси LiteLLM, например http://localhost:4000."$json$::jsonb),
  ('ja', 'gateway.baseUrl.hint.litellm', $json$"LiteLLM プロキシのアドレス（例: http://localhost:4000）。"$json$::jsonb),
  ('de', 'gateway.baseUrl.hint.litellm', $json$"Die Adresse deines LiteLLM-Proxys, zum Beispiel http://localhost:4000."$json$::jsonb),
