  ('pt-BR', 'gateway.apiKey.hint', $json$"Guardada só neste computador: nunca mais é mostrada e nunca vai para a nuvem."$json$::jsonb),
  ('en', 'gateway.apiKey.hint', $json$"Stored only on this computer: never shown again and never synced to the cloud."$json$::jsonb),
  ('es', 'gateway.apiKey.hint', $json$"Se guarda solo en este equipo: no se vuelve a mostrar y nunca se sincroniza con la nube."$json$::jsonb),
  ('zh-CN', 'gateway.apiKey.hint', $json$"仅保存在这台电脑上：不会再次显示，也不会同步到云端。"$json$::jsonb),
  ('hi', 'gateway.apiKey.hint', $json$"केवल इसी कंप्यूटर पर सहेजी जाती है: दोबारा दिखाई नहीं जाती और क्लाउड में सिंक नहीं होती।"$json$::jsonb),
  ('ar', 'gateway.apiKey.hint', $json$"تُحفظ على هذا الحاسوب فقط: لا تُعرض مرة أخرى ولا تُزامَن مع السحابة أبدًا."$json$::jsonb),
  ('fr', 'gateway.apiKey.hint', $json$"Stockée uniquement sur cet ordinateur : jamais ré-affichée et jamais synchronisée dans le cloud."$json$::jsonb),
  ('ru', 'gateway.apiKey.hint', $json$"Хранится только на этом компьютере: больше не показывается и никогда не синхронизируется с облаком."$json$::jsonb),
  ('ja', 'gateway.apiKey.hint', $json$"このコンピューターにのみ保存され、再表示されず、クラウドにも同期されません。"$json$::jsonb),
  ('de', 'gateway.apiKey.hint', $json$"Nur auf diesem Computer gespeichert: wird nie wieder angezeigt und nie mit der Cloud synchronisiert."$json$::jsonb),
  ('pt-BR', 'gateway.apiKey.hint.optional', $json$"Opcional para um proxy LiteLLM sem chave. Guardada só neste computador: nunca mais é mostrada e nunca vai para a nuvem."$json$::jsonb),
  ('en', 'gateway.apiKey.hint.optional', $json$"Optional for a LiteLLM proxy without a key. Stored only on this computer: never shown again and never synced to the cloud."$json$::jsonb),
  ('es', 'gateway.apiKey.hint.optional', $json$"Opcional para un proxy LiteLLM sin clave. Se guarda solo en este equipo: no se vuelve a mostrar y nunca se sincroniza con la nube."$json$::jsonb),
  ('zh-CN', 'gateway.apiKey.hint.optional', $json$"对没有密钥的 LiteLLM 代理为可选项。仅保存在这台电脑上：不会再次显示，也不会同步到云端。"$json$::jsonb),
  ('hi', 'gateway.apiKey.hint.optional', $json$"बिना कुंजी वाले LiteLLM प्रॉक्सी के लिए वैकल्पिक। केवल इसी कंप्यूटर पर सहेजी जाती है: दोबारा दिखाई नहीं जाती और क्लाउड में सिंक नहीं होती।"$json$::jsonb),
  ('ar', 'gateway.apiKey.hint.optional', $json$"اختياري لوكيل LiteLLM بلا مفتاح. يُحفظ على هذا الحاسوب فقط: لا يُعرض مرة أخرى ولا يُزامَن مع السحابة أبدًا."$json$::jsonb),
  ('fr', 'gateway.apiKey.hint.optional', $json$"Facultative pour un proxy LiteLLM sans clé. Stockée uniquement sur cet ordinateur : jamais ré-affichée et jamais synchronisée dans le cloud."$json$::jsonb),
  ('ru', 'gateway.apiKey.hint.optional', $json$"Необязателен для прокси LiteLLM без ключа. Хранится только на этом компьютере: больше не показывается и никогда не синхронизируется с облаком."$json$::jsonb),
  ('ja', 'gateway.apiKey.hint.optional', $json$"キーのない LiteLLM プロキシでは省略できます。このコンピューターにのみ保存され、再表示されず、クラウドにも同期されません。"$json$::jsonb),
  ('de', 'gateway.apiKey.hint.optional', $json$"Optional für einen LiteLLM-Proxy ohne Schlüssel. Nur auf diesem Computer gespeichert: wird nie wieder angezeigt und nie mit der Cloud synchronisiert."$json$::jsonb),
  ('pt-BR', 'gateway.apiKey.saved', $json$"Chave guardada neste computador"$json$::jsonb),
